1	import * as THREE from 'three';
2	import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
3	import { CONFIG } from '../../config';
4	import { rng, clamp } from '../math';
5	
6	/* =====================================================================
7	   HÌNH HỌC CÂY — cây bóng mát (spec G1) và cây dừa (spec G2), thuần (không DOM, không texture).
8	   Dựng theo bản thử docs/superpowers/specs/tham-chieu/cay-va-nguoi/cay-va-nguoi-dung-thu.html nhưng giản lược theo trần tam giác CONFIG.trees.maxTris.
9	   Mọi hình: không index, đủ position / normal / uv / color; mặt quấn ngược chiều kim đồng hồ nhìn từ ngoài.
10	   Không gian chuẩn hóa (instance nhân cỡ thật):
11	   - thân bóng mát: gốc y = 0, đầu cành cao nhất y = 1; ngang tính theo bán kính tán (đầu cành tỏa ≈ 0,7);
12	   - tán bóng mát: trong khối cầu đơn vị tâm gốc tọa độ, color = độ sáng tương đối (màu xanh lấy từ instanceColor);
13	   - thân dừa: cao 1, bán kính đáy 0,35 / đỉnh 0,2 (trước khi instance nhân CONFIG.trees.palm.trunkWidth), đỉnh lệch palm.bend theo +X;
14	   - tán dừa: gốc tọa độ là đỉnh thân, tỉ lệ đều (instance nhân crownScale × h).
15	   Ngẫu nhiên dùng rng(seed) riêng — không gọi rand() chung.
16	   ===================================================================== */
17	const T = CONFIG.trees;
18	type RGB = [number, number, number];
19	const V = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);
20	
21	/* Gói mảng thành BufferGeometry không index */
22	function trGeo(p: number[], n: number[], uv: number[], c: number[]): THREE.BufferGeometry {
23	  const g = new THREE.BufferGeometry();
24	  g.setAttribute('position', new THREE.Float32BufferAttribute(p, 3)); g.setAttribute('normal', new THREE.Float32BufferAttribute(n, 3));
25	  g.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2)); g.setAttribute('color', new THREE.Float32BufferAttribute(c, 3));
26	  return g;
27	}
28	
29	/* Gán màu đỉnh theo hàm vị trí; bỏ index để gộp được với các phần khác */
30	function trPaint(g: THREE.BufferGeometry, fn: (x: number, y: number, z: number) => RGB): THREE.BufferGeometry {
31	  if (g.index) g = g.toNonIndexed();
32	  const p = g.getAttribute('position'), c = new Float32Array(p.count * 3);
33	  for (let i = 0; i < p.count; i++) c.set(fn(p.getX(i), p.getY(i), p.getZ(i)), i * 3);
34	  g.setAttribute('color', new THREE.BufferAttribute(c, 3));
35	  return g;
36	}
37	
38	/* Ống hở hai đầu theo đường gấp khúc: mỗi điểm có bán kính và màu vòng.
39	   flat = true: vòng nằm ngang (thân đứng, kể cả khi cong) ⇒ đáy đúng y = 0, đỉnh đúng cao độ điểm cuối; ngược lại vòng vuông góc với hướng ống (cành). */
40	function trTube(path: { p: THREE.Vector3; r: number; c: RGB }[], sides: number, flat = false): THREE.BufferGeometry {
41	  const P: number[] = [], N: number[] = [], UV: number[] = [], C: number[] = [];
42	  const rings = path.map((s, i) => {
43	    let A = V(1, 0, 0), B = V(0, 0, 1);
44	    if (!flat) {
45	      const t = path[Math.min(i + 1, path.length - 1)].p.clone().sub(path[Math.max(i - 1, 0)].p).normalize();
46	      A = new THREE.Vector3().crossVectors(t, Math.abs(t.y) < 0.9 ? V(0, 1, 0) : V(1, 0, 0)).normalize(); B = new THREE.Vector3().crossVectors(t, A);
47	    } else { B = V(0, 0, -1); }   // vòng ngang: (A, B, +Y) thuận tay phải để mặt quấn ra ngoài
48	    return Array.from({ length: sides + 1 }, (_, j) => { const a = (j / sides) * Math.PI * 2, d = A.clone().multiplyScalar(Math.cos(a)).addScaledVector(B, Math.sin(a)); return { p: s.p.clone().addScaledVector(d, s.r), n: d, u: j / sides, v: i / (path.length - 1), c: s.c }; });
49	  });
50	  const put = (q: { p: THREE.Vector3; n: THREE.Vector3; u: number; v: number; c: RGB }) => { P.push(q.p.x, q.p.y, q.p.z); N.push(q.n.x, q.n.y, q.n.z); UV.push(q.u, q.v); C.push(...q.c); };
51	  for (let i = 0; i < rings.length - 1; i++) for (let j = 0; j < sides; j++) {
52	    const a = rings[i][j], b = rings[i][j + 1], c = rings[i + 1][j + 1], d = rings[i + 1][j];
53	    put(a); put(b); put(c); put(a); put(c); put(d);
54	  }
55	  return trGeo(P, N, UV, C);
56	}
57	
58	/* ---------- Cây bóng mát: thân + cành ---------- */
59	/* Gốc xòe, thân thẳng tới chỗ tách (fork), 1 cành giữa gần thẳng đứng + các cành tỏa hình vòng cung; mỗi cành 2 đoạn */
60	export function trShadeTrunkGeo(): THREE.BufferGeometry {
61	  const S = T.shade, r = rng(S.seed), bark = (y: number): RGB => { const k = 0.82 + 0.18 * Math.sin(y * 23); return [0.46 * k, 0.4 * k, 0.34 * k]; };   // nâu xám, vằn nhẹ theo cao
62	  const parts = [trTube([[0, 0.17], [0.06, 0.11], [0.2, 0.09], [S.fork + 0.02, 0.075]].map(([y, rr]) => ({ p: V(0, y, 0), r: rr, c: bark(y) })), S.sides, true)];
63	  for (let i = 0; i < S.branches; i++) {
64	    const centre = i === 0, yaw = (i - 1) * (Math.PI * 2 / (S.branches - 1)) + r() * 0.5;
65	    const reach = centre ? 0.1 : S.reach * (0.86 + r() * 0.14), top = centre ? 1 : 0.84 + r() * 0.1, dx = Math.cos(yaw), dz = Math.sin(yaw);
66	    const a = V(dx * 0.02, S.fork - 0.04, dz * 0.02), b = V(dx * reach * 0.42, S.fork + (top - S.fork) * 0.62, dz * reach * 0.42), c = V(dx * reach, top, dz * reach);
67	    parts.push(trTube([{ p: a, r: 0.055, c: bark(a.y) }, { p: b, r: 0.035, c: bark(b.y) }, { p: c, r: 0.014, c: bark(c.y) }], S.sides));
68	  }
69	  const g = mergeGeometries(parts); g.computeBoundingBox();
70	  g.scale(1, 1 / g.boundingBox!.max.y, 1);   // đầu cành cao nhất đúng y = 1 (vòng đầu cành giữa hơi nghiêng)
71	  return g;
72	}
73	
74	/* ---------- Cây bóng mát: tán ---------- */
75	/* Các cụm lá khối 20 mặt chia 1 lần (80 tam giác) nhiễu nhẹ, xếp vành ngoài thấp + vành giữa + đỉnh như bản thử.
76	   Pháp tuyến hướng từ tâm cụm (bóng mềm); color = độ sáng: sáng ở trên ≈ 1, sẫm ở dưới và trong khe giữa các cụm ≈ 0,4. */
77	export function trShadeCrownGeo(): THREE.BufferGeometry {
78	  const S = T.shade, r = rng(S.seed + 1), blobs: { c: THREE.Vector3; s: THREE.Vector3 }[] = [];
79	  const add = (a: number, rr: number, y: number, s: number) => blobs.push({ c: V(Math.cos(a) * rr, y, Math.sin(a) * rr), s: V(s, s * 0.85, s) });
80	  for (let i = 0; i < S.blobs.outer; i++) add(i * (Math.PI * 2 / S.blobs.outer) + (r() - 0.5) * 0.3, 0.52 + r() * 0.05, -0.37 + r() * 0.06, 0.41 + r() * 0.04);   // vành ngoài, thấp
81	  for (let i = 0; i < S.blobs.mid; i++) add(i * (Math.PI * 2 / S.blobs.mid) + 0.6 + r() * 0.4, 0.26 + r() * 0.06, 0.1 + r() * 0.06, 0.47 + r() * 0.04);   // vành giữa
82	  for (let i = 0; i < S.blobs.top; i++) add(r() * 6.28, 0.06, 0.38 + r() * 0.04, 0.48);                                                                  // đỉnh
83	  const inside = (q: THREE.Vector3, skip: number) => blobs.some((b, k) => k !== skip && q.clone().sub(b.c).divide(b.s).length() < 1.05);
84	  const parts = blobs.map((b, k) => {
85	    const g = new THREE.IcosahedronGeometry(1, 1), p = g.getAttribute('position'), n = g.getAttribute('normal'), sd = r() * 20, q = new THREE.Vector3(), d = new THREE.Vector3();
86	    const c = new Float32Array(p.count * 3);
87	    for (let i = 0; i < p.count; i++) {
88	      d.fromBufferAttribute(p, i).normalize();
89	      const kk = 1 + 0.09 * Math.sin(d.x * 3.1 + sd) * Math.sin(d.y * 2.7 + sd * 1.7) * Math.sin(d.z * 2.9 + sd * 0.6) + 0.04 * Math.sin(d.x * 7 + sd) * Math.sin(d.y * 8 + d.z * 6 + sd);
90	      q.copy(d).multiplyScalar(kk).multiply(b.s).add(b.c);
91	      if (q.length() > 1.1) q.setLength(1.1);   // giữ trong cầu đơn vị (khế ước với instance)
92	      p.setXYZ(i, q.x, q.y, q.z);
93	      const nm = V(d.x / b.s.x, d.y / b.s.y, d.z / b.s.z).normalize(); n.setXYZ(i, nm.x, nm.y, nm.z);
94	      const h = clamp((q.y + 0.75) / 1.6, 0, 1), up = clamp(0.5 + 0.5 * nm.y, 0, 1);
95	      let s = 0.4 + 0.6 * (0.55 * h + 0.45 * up);
96	      if (inside(q, k)) s = 0.4 + (s - 0.4) * 0.35;   // khe giữa các cụm: sẫm
97	      c[i * 3] = c[i * 3 + 1] = c[i * 3 + 2] = s;
98	    }
99	    g.setAttribute('color', new THREE.BufferAttribute(c, 3));
100	    return g;
101	  });
102	  return mergeGeometries(parts);
103	}
104	
105	/* ---------- Cây dừa: thân ---------- */
106	/* Cao 1, vòng ngang (không nghiêng theo độ cong) để đỉnh đúng y = 1; gốc phình; cong x = bend · y²; vòng sẹo = màu vòng sáng / sẫm xen kẽ */
107	const PALM_RINGS = 10, PALM_SIDES = 6;   // 10 đoạn × 6 cạnh × 2 = 120 tam giác
108	export function trPalmTrunkGeo(): THREE.BufferGeometry {
109	  const path = Array.from({ length: PALM_RINGS + 1 }, (_, i) => {
110	    const y = Math.pow(i / PALM_RINGS, 1.25), rr = 0.2 + 0.08 * (1 - y) + 0.07 * Math.pow(Math.max(0, 1 - y / 0.12), 2), k = i % 2 ? 0.74 : 1;   // vòng dày ở gốc cho chỗ phình
111	    return { p: V(T.palm.bend * y * y, y, 0), r: rr, c: [0.6 * k, 0.55 * k, 0.48 * k] as RGB };
112	  });
113	  return trTube(path, PALM_SIDES, true);
114	}
